class Parent:
    def implicit(self):
        print("PARENT implicit()")

    def override(self):
        print("PARENT override()")

    def altered(self):
        print("PARENT altered()")


class Child(Parent):
    def override(self):
        print("CHILD override()")

    def altered(self):
        print("CHILD, BEFORE PARENT altered()")
        super().altered()
        print("CHILD, AFTER PARENT altered()")


print("=== Inheritance ===")
dad = Parent()
son = Child()
dad.implicit()
son.implicit()
dad.override()
son.override()
dad.altered()
son.altered()


class Other:
    def override(self):
        print("OTHER override()")

    def implicit(self):
        print("OTHER implicit()")

    def altered(self):
        print("OTHER altered()")


class Composed:
    def __init__(self):
        self.other = Other()

    def implicit(self):
        self.other.implicit()

    def override(self):
        print("COMPOSED override()")

    def altered(self):
        print("COMPOSED, BEFORE OTHER altered()")
        self.other.altered()
        print("COMPOSED, AFTER OTHER altered()")


print("\n=== Composition ===")
c = Composed()
c.implicit()
c.override()
c.altered()
